import express from "express";
import helmet from "helmet";
import cors from "cors";
import { randomUUID } from "node:crypto";
import { ticketsRouter } from "./routes/tickets.js";

export const app=express();
app.disable("x-powered-by");
app.set("trust proxy","loopback");
app.use(helmet());
app.use(express.json({limit:"100kb"}));
const allowed=new Set(["https://app.example.test"]);
app.use(cors({origin:(origin,cb)=>cb(null,!origin||allowed.has(origin)),credentials:true}));
app.use((req,res,next)=>{const id=randomUUID();const started=Date.now();req.requestId=id;res.set("X-Request-ID",id);res.on("finish",()=>console.log(JSON.stringify({id,method:req.method,path:req.originalUrl,status:res.statusCode,ms:Date.now()-started})));next();});
app.get("/health/live",(req,res)=>res.json({status:"alive"}));
app.get("/health/ready",(req,res)=>res.json({status:"ready"}));
app.use("/api/v1/tickets",ticketsRouter);
app.use((req,res)=>res.status(404).json({error:"not_found",requestId:req.requestId}));
app.use((err,req,res,next)=>{console.error(err);const status=Number.isInteger(err.statusCode)?err.statusCode:500;res.status(status).json({error:status<500?(err.code||"request_error"):"internal_error",requestId:req.requestId});});

