import { app } from "./app.js";
const port=Number(process.env.PORT??3000);
if(!Number.isInteger(port)||port<1||port>65535)throw new Error("Invalid PORT");
const server=app.listen(port,()=>console.log(`Listening on ${port}`));
let shuttingDown=false;
async function closeResources(){}
function shutdown(signal){if(shuttingDown)return;shuttingDown=true;console.log(`${signal} received`);server.close(async(error)=>{await closeResources();if(error){console.error(error);process.exitCode=1;}process.exit();});}
process.on("SIGTERM",()=>shutdown("SIGTERM"));
process.on("SIGINT",()=>shutdown("SIGINT"));

