import express from "express";
import { ticketService } from "../services/ticketService.js";
import { validateTicket } from "../middleware/validateTicket.js";
export const ticketsRouter=express.Router();
function query(q){const page=Number(q.page??1),limit=Number(q.limit??20);if(!Number.isInteger(page)||page<1)throw Object.assign(new Error("invalid page"),{statusCode:400,code:"invalid_page"});if(!Number.isInteger(limit)||limit<1)throw Object.assign(new Error("invalid limit"),{statusCode:400,code:"invalid_limit"});return{page,limit:Math.min(limit,100)};}
ticketsRouter.get("/",async(req,res)=>{const q=query(req.query);const result=await ticketService.list(q);res.json({...result,...q});});
ticketsRouter.get("/:id",async(req,res)=>res.json(await ticketService.getById(req.params.id)));
ticketsRouter.post("/",validateTicket,async(req,res)=>res.status(201).json(await ticketService.create(req.validatedTicket)));
ticketsRouter.patch("/:id/status",async(req,res)=>res.json(await ticketService.updateStatus(req.params.id,req.body?.status)));

