import { AppError } from "../errors/AppError.js";
import { ticketRepository } from "../repositories/ticketRepository.js";
export const ticketService={list:q=>ticketRepository.list(q),async getById(id){const t=await ticketRepository.findById(id);if(!t)throw new AppError(404,"ticket_not_found","Ticket was not found");return t;},create:input=>ticketRepository.create(input),async updateStatus(id,status){if(!["open","in_progress","resolved"].includes(status))throw new AppError(400,"invalid_status","Status is invalid");const t=await ticketRepository.updateStatus(id,status);if(!t)throw new AppError(404,"ticket_not_found","Ticket was not found");return t;}};

