import test from "node:test";import assert from "node:assert/strict";import {app} from "../src/app.js";
async function withServer(fn){const server=app.listen(0);try{const {port}=server.address();return await fn(`http://127.0.0.1:${port}`);}finally{await new Promise(r=>server.close(r));}}
test("health",async()=>withServer(async base=>{const r=await fetch(`${base}/health/live`);assert.equal(r.status,200);assert.deepEqual(await r.json(),{status:"alive"});}));
test("create ticket",async()=>withServer(async base=>{const r=await fetch(`${base}/api/v1/tickets`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({title:"Access issue",priority:"high"})});assert.equal(r.status,201);const b=await r.json();assert.equal(b.title,"Access issue");}));
test("validation",async()=>withServer(async base=>{const r=await fetch(`${base}/api/v1/tickets`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({title:""})});assert.equal(r.status,400);const b=await r.json();assert.equal(b.error,"invalid_title");}));
